'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),path=require('node:path'),fs=require('node:fs');
const {chromium,executablePath}=require('../scripts/codex/browser.cjs');
const TestUI=require('./browser-origin.cjs');
const {serveBrowserFixture,selectChoice,readChoice}=TestUI;
const root=path.resolve(__dirname,'..');
async function openGame(page,game,mode='hotseat'){await TestUI.ready(page);return TestUI.openGame(page,game,mode);}
async function roomContext(page){
  await page.locator('.room-setup-modal [data-room-context]').click();
  await page.locator('.room-context-modal').waitFor();
}
async function roomParameters(page){await TestUI.activeSurface(page).locator('.room-v021-game-context').click();await TestUI.activeSurface(page).locator('#room-rules-form').waitFor();}
async function backFrom(page,surface){
  await page.locator(`${surface} .modal-head [data-command="close-modal"]`).click();
}
async function closeRoom(page){
  await roomContext(page);await page.locator('.room-context-modal [data-command="lobby-leave"]').click();
  await page.locator('[data-confirm-accept]').click();await page.locator('.game-grid').waitFor();
  await page.waitForFunction(()=>PlayroomAppBridge.room()===null);
}
async function capture(page,name){
  if(!process.env.PLAYROOM_CAPTURE_DIR)return;
  fs.mkdirSync(process.env.PLAYROOM_CAPTURE_DIR,{recursive:true});
  await page.screenshot({path:path.join(process.env.PLAYROOM_CAPTURE_DIR,name+'.png'),animations:'disabled'});
}
async function quietContext(browser,options={}){
  const context=await browser.newContext({...options,reducedMotion:'reduce'});
  await context.addInitScript(()=>localStorage.setItem('playroom.settings.v1',JSON.stringify({sound:false,tutorialsEnabled:false})));
  return context;
}

