test('Finished Offline match restores its saved lobby and starts a separate clean session',{timeout:30000},async()=>{
  const server=await serveBrowserFixture(root),browser=await chromium.launch({headless:true,executablePath:executablePath(),args:['--no-sandbox','--disable-background-networking']});
  const context=await browser.newContext({viewport:{width:390,height:740}}),page=await context.newPage();page.setDefaultTimeout(7000);
  try{
    await page.goto(server.url);await page.locator('[data-start=uno]').click();await page.locator('[data-game-mode=hotseat]').click();
    const expected=await page.evaluate(async()=>{
      const b=PlayroomAppBridge,id=b.room().id,host=b.participantId();
      b.roomService.renameLocalSeat(id,host,'seat-2','Кира');
      b.roomService.setLocalSeat(id,host,'seat-3',{kind:'human',nickname:'Мария'});
      b.roomService.moveParticipant(id,host,host,'seat-3');
      const room=b.roomService.configure(id,host,{name:'Повторяем вместе',firstPlayerMode:'assigned',firstParticipantId:host});
      const players=room.seats.filter(s=>s.participantId).map(s=>{const p=room.participants.find(p=>p.id===s.participantId);return {name:p.nickname,bot:p.bot};});
      let session=null;for(let seed=1;seed<=20&&!session;seed++){const candidate=new TabletopSession(TabletopCore,room.game.id,{players,mode:'pass',lobbyConfig:room,preset:room.rules.preset,presetLabel:room.rules.presetLabel,openHands:room.rules.openHands,firstPlayerMode:'assigned',firstPlayer:2,...room.rules.options,seed});for(let step=0;step<5000;step++){const actor=candidate.current.turn,action=TabletopCore.botAction(candidate.current,actor);if(!action)throw Error('Legal terminal fixture has no action');const next=candidate.prepare(actor,action);if(next.status==='finished'){if(candidate.current.players[actor].bot)session=candidate;break;}candidate.commitPrepared(next);}}if(!session)throw Error('Legal bot-terminal prefix not found');await b.saveLibrary.activateAsync(session,'qa-complete');
      return {name:room.name,seats:room.seats.map(s=>s.participantId),participants:room.participants.map(p=>({id:p.id,name:p.nickname,bot:p.bot,seat:p.seatId})),first:host,rules:room.rules};
    });
    await page.reload();await TestUI.ready(page);await TestUI.resumeSaved(page,'qa-complete');await page.waitForFunction(()=>PlayroomAppBridge.saveLibrary.current().session.current.status==='finished');if(await TestUI.activeSurface(page).locator('[data-learning-choice=no]').count())await TestUI.activeSurface(page).locator('[data-learning-choice=no]').click();if(!await TestUI.activeSurface(page).locator('.result-modal').count()){await page.locator('[data-game-menu]').click();await TestUI.activeSurface(page).locator('[data-command=result]').click();}await TestUI.activeSurface(page).locator('.result-modal').waitFor();await TestUI.activeSurface(page).locator('[data-command=rematch]').click();await page.locator('.room-setup-modal .room-v021').waitFor();
    const actual=await page.evaluate(()=>{const r=PlayroomAppBridge.room();return {name:r.name,seats:r.seats.map(s=>s.participantId),participants:r.participants.map(p=>({id:p.id,name:p.nickname,bot:p.bot,seat:p.seatId})),first:r.firstParticipantId,rules:r.rules};});
    assert.deepEqual(actual,expected);
    await page.locator('[data-command=lobby-start]').click();await page.waitForFunction(()=>PlayroomAppBridge.saveLibrary.currentId()!=='qa-complete'&&PlayroomAppBridge.saveLibrary.current().session.current.status==='playing');await page.locator('.table-shell').waitFor();
    const next=await page.evaluate(()=>{const current=PlayroomAppBridge.saveLibrary.current(),s=current.session;return {id:current.id,move:s.current.move,status:s.current.status,old:PlayroomAppBridge.saveLibrary.list().some(item=>item.id==='qa-complete')};});
    assert.notEqual(next.id,'qa-complete');assert.equal(next.move,0);assert.equal(next.status,'playing');assert.equal(next.old,true);
  }finally{await context.close();await browser.close();await server.close();}
});

