  const ludo=await pageFor();await TestUI.openGame(ludo,'ludo');await mode(ludo,'teams');assert.equal(await active(ludo).locator('[data-room-seat] .player-medallion.is-team').count(),4);assert.equal(await active(ludo).locator('.room-v021-empty .player-medallion.is-team').count(),2);await ludo.screenshot({path:path.join(out,'ludo-empty-team-slots.png')});
